#pragma once

#include <QStringList>

// The fonts heap ships inside the binary (qrc :/fonts, generated by
// tools/gen_bundled_fonts.py): Inter 400/500/600 for the interface, Golos Text
// 400/500/600 for headings and the wordmark, and JetBrains Mono 400/500 for
// code, ids and times. Golos was the interface's face until 0.9.3: it carries
// no hinting, and at 13-15 px on a 100 % screen it read soft (owner). Before
// they were bundled the
// UI asked for fonts most machines do not have and drew in Segoe UI / Consolas
// on Windows, something else on Linux and macOS.
//
// They are registered as "Tabless Golos Text" / "Tabless JetBrains Mono", never the
// upstream names: on Windows with JetBrains Mono installed, a bundled face
// under the same name got mixed with the installed one (glyph ids from one
// file, outlines from the other) and every time and count read as gibberish.
namespace heap::platform {

inline constexpr const char* kUiFontFamily = "Tabless Inter";
inline constexpr const char* kDisplayFontFamily = "Tabless Golos Text";
inline constexpr const char* kMonoFontFamily = "Tabless JetBrains Mono";
// The third text face Settings → Appearance → Font offers (APP-314).
inline constexpr const char* kOnestFontFamily = "Tabless Onest";

// Adds every bundled face to the application font database. Call once, after
// the QGuiApplication exists and before any QML loads. A face that cannot be
// added is logged as a warning; returns how many failed (0 = all in).
int registerBundledFonts();

// Makes Inter the application font (family only; the size stays the
// platform's). Text with no family of its own, the Controls' defaults and a
// font.family the machine does not have all end up in it, not in the system
// UI font. No-op when the family did not register.
void useBundledUiFontByDefault();

// What the font database cannot give back after registration: a missing
// family ("Golos Text") or a weight that resolves to another one
// ("Golos Text 600"). Empty when everything is there. --smoke reports these.
QStringList missingBundledFonts();

}  // namespace heap::platform
